CREATE FUNCTION ecc_audit_application_details() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 INSERT INTO audit_log(entity_type,entity_id,action,changes,actor_id) VALUES('case',NEW.id,'updated',(SELECT jsonb_object_agg(key,value)::text FROM jsonb_each(jsonb_build_object('institution',jsonb_build_object('from',OLD.institution,'to',NEW.institution),'program',jsonb_build_object('from',OLD.program,'to',NEW.program),'offer_status',jsonb_build_object('from',OLD.offer_status,'to',NEW.offer_status),'enrollment_status',jsonb_build_object('from',OLD.enrollment_status,'to',NEW.enrollment_status))) WHERE value->'from' IS DISTINCT FROM value->'to'),(SELECT actor_id FROM request_context WHERE id=1));
 RETURN NEW;
END $$;
CREATE TRIGGER audit_application_details AFTER UPDATE OF institution,program,offer_status,enrollment_status ON cases FOR EACH ROW WHEN (OLD.institution IS DISTINCT FROM NEW.institution OR OLD.program IS DISTINCT FROM NEW.program OR OLD.offer_status IS DISTINCT FROM NEW.offer_status OR OLD.enrollment_status IS DISTINCT FROM NEW.enrollment_status) EXECUTE FUNCTION ecc_audit_application_details();
